import {REQUIREMENTS,DOMAINS,DOCS,MATURITY_CONTROLS,MATURITY_DOMAINS,STATUS_LABEL,STATUS,REVIEWS,STEPS,STRIDE,SME_CONTROLS,SME_DOMAINS,REGULATORY_BASELINE,LAW} from './data.js';
import {newProduct,uid,scope,requirementMetrics,maturityMetrics,relevantRequirements,riskRating,releaseReview,createSnapshot,compareSnapshot,reportingDeadlines,safeText as esc,isoDate} from './engine.js';
import {loadWorkspace,persistWorkspace,exportWorkspace,downloadText,parseBackup,getProduct} from './store.js';
import {readSbom} from './sbom.js';
import {encryptWorkspace,decryptWorkspace,isEncryptedBackup} from './secure-backup.js';

const app=document.querySelector('#app');
let work=loadWorkspace();let page='overview';let filter='all';let search='';let toastText='';let storageFailure=false;let maturityMode='professional';
const ROUTES=[['overview','Overview','01'],['product','Product & scope','02'],['requirements','Requirements','03'],['maturity','Security maturity','04'],['traceability','Traceability','05'],['evidence','Evidence register','06'],['risks','Threats & risks','07'],['actions','Action plan','08'],['releases','Release reviews','09'],['sbom','SBOM explorer','10'],['vulnerabilities','Vulnerabilities','11'],['reporting','Incident reporting','12'],['documents','Documentation','13'],['settings','Data & settings','14']];
const attr=v=>esc(v);const option=(v,t,current)=>`<option value="${attr(v)}" ${String(v)===String(current)?'selected':''}>${esc(t)}</option>`;
const selected=(list,current)=>list.map(([v,t])=>option(v,t,current)).join('');
const select=(name,options,value)=>`<select name="${attr(name)}">${selected(options,value)}</select>`;
const input=(name,val='',type='text',placeholder='')=>`<input type="${type}" name="${attr(name)}" value="${attr(val)}" placeholder="${attr(placeholder)}"/>`;
const textarea=(name,val='',placeholder='')=>`<textarea name="${attr(name)}" rows="3" placeholder="${attr(placeholder)}">${esc(val)}</textarea>`;
const field=(title,content,description='')=>`<label class="field"><span>${title}</span>${content}${description?`<small>${description}</small>`:''}</label>`;
const tag=(text,tone='neutral')=>`<span class="tag ${tone}">${esc(text)}</span>`;
function notify(message){toastText=message;render();}
function save(){const p=getProduct(work);if(p)p.updated=new Date().toISOString();try{persistWorkspace(work);storageFailure=false;}catch(e){storageFailure=true;}render();}
function navigate(p){page=ROUTES.some(x=>x[0]===p)?p:'overview';location.hash=page;filter='all';search='';render();window.scrollTo({top:0,behavior:'instant'});}
function header(title,sub='',actions=''){return `<header class="page-header"><div><span class="eyebrow">CRA / PRODUCT ASSURANCE</span><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div>${actions?`<div class="page-header-actions">${actions}</div>`:''}</header>`;}
function notice(text,kind='info'){return `<div class="notice ${kind}"><span class="notice-icon">i</span><p>${text}</p></div>`;}
function empty(title,description,cta=''){return `<div class="empty"><span class="empty-mark">◎</span><h3>${esc(title)}</h3><p>${esc(description)}</p>${cta}</div>`;}
function btn(label,act,cls=''){return `<button type="button" class="button ${cls}" data-action="${act}">${label}</button>`;}
function metric(value,title,note=''){return `<div class="metric"><span class="metric-label">${esc(title)}</span><strong>${esc(value)}</strong><span class="metric-note">${esc(note)}</span></div>`;}
function p(){return getProduct(work);}
function requireProduct(title){return empty('Create a product to begin',`${title} becomes available once a product profile exists.`,btn('Create product','new-product','primary'));}
function productSelector(){const name=p()?.name||'No product selected';return `<div class="product-selector"><span>WORKSPACE</span><select aria-label="Current product" id="choose-product"><option value="" ${p()?'':'selected'} disabled>${esc(name)}</option>${work.products.map(x=>option(x.id,`${x.name} · ${x.version||'version not set'}`,p()?.id)).join('')}</select></div>`;}
function frame(){const current=ROUTES.find(x=>x[0]===page)?.[1]||'Overview';return `<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-logo"><svg viewBox="0 0 48 48" aria-hidden="true"><path d="M7 12h34M7 24h25M7 36h34" stroke="currentColor" stroke-width="3.5" stroke-linecap="round"/><circle cx="37" cy="24" r="5" fill="currentColor"/></svg></span><span><strong>CRA Readiness</strong><small>STUDIO / PRODUCT SECURITY</small></span></div>${productSelector()}<nav class="navigation" aria-label="Application modules">${ROUTES.map(([id,label,number])=>`<button class="nav-link ${page===id?'active':''}" data-nav="${id}" ${page===id?'aria-current="page"':''}><span class="nav-numeral">${number}</span>${esc(label)}${id==='actions'&&p()?.actions.some(a=>a.status!=='closed')?'<span class="nav-dot"></span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><span class="green-dot"></span> Local-first workspace<p>Data remains in this browser unless you export it. Not a regulatory certification service.</p><span class="legal-reference">Regulation (EU) 2024/2847</span></div></aside><div class="main-shell"><div class="topbar"><button class="mobile-menu" data-action="mobile-nav" aria-label="Toggle menu">☰</button><div class="breadcrumb">Product Security <span>/</span> ${esc(current)}</div><div class="top-actions"><span class="local-label"><span class="green-dot"></span> Saved locally</span>${btn('Export backup','export-workspace','quiet')}${btn('+ New product','new-product','primary small')}</div></div><main id="content" tabindex="-1">${content()}</main><footer class="footer"><span>CRA READINESS STUDIO · Independent assessment workspace</span><span>Regulatory baseline: EU 2024/2847 · Reviewed Oct 2026</span></footer></div></div>${toastText?`<div role="status" class="toast">${esc(toastText)} <button data-action="clear-toast" aria-label="Dismiss notice">×</button></div>`:''}`;}
function overview(){const x=p();const m=x?requirementMetrics(x):null;const check=x?releaseReview(x):null;
 return `${header('Product security, made reviewable.','Connect your regulatory assessment to engineering risks, evidence, actions and release decisions.',btn('Create product','new-product','primary'))}
 <section class="hero"><div class="hero-main"><span class="overline">ENGINEERED FOR EVIDENCE</span><h2>Move beyond the<br><em>compliance checklist.</em></h2><p>A transparent, local-first workspace for analysing CRA applicability, tracking technical assurance and building a defensible documentation trail.</p><div class="button-line">${btn(x?'Continue assessment':'Start assessment',x?'requirements':'new-product','primary')}${btn('Review legal basis','reference','outline')}</div></div><div class="hero-art" aria-hidden="true"><div class="graph-line"></div><div class="graph-node n1"><span>01</span>RISK</div><div class="graph-node n2"><span>02</span>CONTROL</div><div class="graph-node n3"><span>03</span>EVIDENCE</div><div class="graph-node n4"><span>04</span>REVIEW</div><div class="hero-tiny">ASSURANCE CHAIN / 2026</div></div></section>
 ${x?`<section class="section"><div class="section-title"><h2>${esc(x.name)}</h2>${tag(scope(x).status,'blue')}</div><div class="metrics four">${metric(m.coverage+'%','Assessment coverage',m.assessed+' of '+m.total+' prompts reviewed')}${metric(m.implementation===null?'—':m.implementation+'%','Implemented, of rated','Not a conformity score')}${metric(m.linkedAccepted+'/'+m.total,'Accepted evidence links','Reviewer-accepted references')}${metric(check.issues.length,'Release review flags','Items for human disposition')}</div></section>
 <div class="two-col section"><div class="panel"><div class="section-title"><h3>Assessment status</h3>${btn('Open requirements →','requirements','link')}</div>${DOMAINS.map(d=>{const rs=relevantRequirements(x).filter(r=>r.domain===d);const done=rs.filter(r=>x.requirements[r.id]?.status&&x.requirements[r.id].status!=='not-assessed').length;return `<div class="progress-row"><div class="progress-title"><span>${esc(d)}</span><strong>${done}/${rs.length}</strong></div><div class="progress"><span style="width:${rs.length?Math.round(done/rs.length*100):0}%"></span></div></div>`;}).join('')}</div><div class="panel"><div class="section-title"><h3>Release review</h3>${btn('Review release →','releases','link')}</div>${check.issues.length?`<ul class="issue-list">${check.issues.slice(0,5).map(i=>`<li>${esc(i)}</li>`).join('')}</ul>`:notice('No rule-based flags in the current recorded dataset. An authorised reviewer must still decide readiness.','success')}</div></div>`:`<div class="two-col section"><div class="panel intro-panel"><div class="eyebrow">THE WORKFLOW</div><h3>Scope → assess → substantiate → review</h3><p>Start with a product profile. Add risks and requirements, connect evidence, record actions, and review changes across releases.</p></div><div class="panel intro-panel"><div class="eyebrow">DESIGN PRINCIPLES</div><h3>Local, transparent, independent</h3><p>No account or external API. The application deliberately distinguishes an assessor's statements from reviewed evidence and legal conformity.</p></div></div>`}
 <div class="section"><div class="section-title"><h2>Core modules</h2><span class="subtle">Purpose-built, without unnecessary features</span></div><div class="feature-grid">${[['traceability','Linked assurance','Connect CRA prompts to risks, actions, and accepted evidence.'],['sbom','Software components','Inspect CycloneDX and SPDX inventories locally.'],['documents','Technical file','Track the supporting documents expected for a structured review.']].map(([id,t,s])=>`<button class="feature" data-nav="${id}"><span class="feature-symbol">↗</span><strong>${t}</strong><p>${s}</p><span class="feature-link">Open module →</span></button>`).join('')}</div></div>`;
}
function productPage(){const x=p();return `${header('Product & applicability','Record inputs and rationale. The result is a screening aid, not an automated legal determination.')}${!x?requireProduct('Product & scope'):`${notice('Scope classification needs qualified review, especially for exemptions, open-source supply, product categories and substantial modifications.')}<div class="two-col"><form class="panel form-layout" data-form="profile"><div class="section-title"><h3>Product profile</h3>${tag('Draft · local','blue')}</div><div class="form-grid">${field('Product name',input('name',x.name))}${field('Product version',input('version',x.version))}${field('Organisation',input('organisation',x.organisation))}${field('Assessment owner',input('owner',x.owner))}${field('Assessor',input('assessor',x.assessor))}${field('Primary economic operator',select('role',[['manufacturer','Manufacturer'],['importer','Importer'],['distributor','Distributor'],['steward','Open-source steward'],['other','Other / review needed']],x.role))}${field('Product or component with digital elements?',select('digital',[['unknown','Needs review'],['yes','Yes'],['no','No']],x.digital))}${field('Made available on the EU market?',select('eu',[['unknown','Needs review'],['yes','Yes'],['no','No']],x.eu))}${field('Commercial activity?',select('commercial',[['unknown','Needs review'],['yes','Yes'],['no','No / unclear']],x.commercial))}${field('Possible sector exclusion?',select('exemption',[['unknown','Needs review'],['no','None identified'],['yes','Potential exemption']],x.exemption))}${field('Preliminary category',select('category',[['unconfirmed','Unconfirmed'],['default','Default'],['class-i','Important Class I'],['class-ii','Important Class II'],['critical','Critical product']],x.category))}${field('First EU placing on market',input('placed',x.placed,'date'))}${field('Support period end',input('supportEnd',x.supportEnd,'date'))}</div>${field('Intended purpose and system context',textarea('purpose',x.purpose),'State intended users, operating environment and security-relevant interfaces.')}${field('Scope rationale / reviewer decision',textarea('scopeRationale',x.scopeRationale))}<button type="submit" class="button primary">Save product profile</button></form><div class="right-column"><div class="panel"><div class="eyebrow">PRELIMINARY SCREENING</div><h2>${esc(scope(x).status)}</h2><p class="subtle">${esc(scope(x).reason)}</p><div class="thin-rule"></div><h4>Conformity route</h4><p class="small">Recorded category: <strong>${esc(x.category)}</strong>. A conformity-assessment route cannot be reliably selected from this field alone. Verify the product's core functionality, standards coverage and applicable procedures under Article 32.</p></div><div class="panel"><h3>Key timing</h3><ul class="dates"><li><b>11 September 2026</b><span>Article 14 reporting obligations apply</span></li><li><b>11 December 2027</b><span>Main CRA obligations apply, subject to transition rules</span></li></ul></div></div></div>`}`;}
function requirementsPage(){const x=p();if(!x)return header('Requirements')+requireProduct('Requirements');const items=relevantRequirements(x).filter(r=>(filter==='all'||(filter==='open'?!(x.requirements[r.id]?.status&&x.requirements[r.id].status!=='not-assessed'):r.domain===filter))&&`${r.id} ${r.title} ${r.guidance} ${r.ref}`.toLowerCase().includes(search.toLowerCase()));const m=requirementMetrics(x);
 return `${header('Regulatory assessment','118 structured assessment prompts across 11 review domains with internal article and annex references.',btn('View traceability →','traceability','outline'))}${notice('Editorial assessment checks linked to CRA articles and annexes. Completion does not establish legal conformity; a qualified reviewer must validate applicability, requirements and supporting evidence.')}
 <div class="metrics four tight">${metric(m.assessed+'/'+m.total,'Reviewed prompts')}${metric(m.implemented,'Marked implemented')}${metric(m.criticalOpen,'Open priority prompts')}${metric(m.linkedAccepted,'Accepted evidence links')}</div><div class="filters"><label><span class="sr-only">Search requirements</span><input id="requirement-search" value="${attr(search)}" placeholder="Search ID, clause, control or keyword..."/></label><label><span class="sr-only">Filter domain</span><select id="requirements-filter">${selected([['all','All areas'],['open','Not assessed'],...DOMAINS.map(t=>[t,t])],filter)}</select></label><span class="subtle">${items.length} results</span></div><div class="req-list">${items.map(r=>requirementCard(x,r)).join('')}</div>`;}
function requirementCard(x,r){const a=x.requirements[r.id]||{},ev=x.evidence.filter(e=>(e.requirementIds||[]).includes(r.id));return `<details class="requirement" id="r-${r.id}"><summary><span class="ref-id">${r.id}</span><div class="requirement-title"><strong>${esc(r.title)}</strong><span>${esc(r.ref)} · ${esc(r.domain)}</span></div>${tag(STATUS_LABEL[a.status]||'Not assessed',a.status==='implemented'?'success':a.status==='gap'?'danger':'neutral')}<span class="expand">⌄</span></summary><div class="requirement-body"><p>${esc(r.guidance)}</p><div class="inline-form"><label class="field"><span>Recorded outcome</span><select data-requirement="${r.id}" data-req-field="status">${selected(STATUS.map(s=>[s,STATUS_LABEL[s]]),a.status||'not-assessed')}</select></label><label class="field"><span>Reviewer</span><input data-requirement="${r.id}" data-req-field="reviewer" value="${attr(a.reviewer||'')}"/></label></div><label class="field"><span>Rationale, exceptions and observations</span><textarea data-requirement="${r.id}" data-req-field="notes" rows="3">${esc(a.notes||'')}</textarea></label>${a.status==='not-applicable'?notice('Record a defensible N/A rationale. N/A is never auto-approved.','warn'):''}<div class="related"><span>Linked evidence: <strong>${ev.length}</strong> (${ev.filter(e=>e.review==='accepted').length} accepted)</span><span>Risk links: <strong>${x.risks.filter(z=>(z.requirementIds||[]).includes(r.id)).length}</strong></span><button data-nav="evidence" class="button link">Evidence register →</button></div><div class="save-row">${btn('Add linked evidence','evidence-for:'+r.id,'outline small')}<span class="legal-reference">${esc(r.ref)}</span></div></div></details>`;}
function maturityPage(){
 const x=p();if(!x)return header('Security maturity')+requireProduct('Security maturity');
 const professional=maturityMode==='professional',controls=professional?MATURITY_CONTROLS:SME_CONTROLS,domains=professional?MATURITY_DOMAINS:SME_DOMAINS;
 const m=maturityMetrics(x,controls);
 const toggles=`<div class="edition-tabs"><button type="button" class="button ${professional?'primary':'outline'}" data-action="maturity-mode:professional">Professional / 150 controls</button><button type="button" class="button ${professional?'outline':'primary'}" data-action="maturity-mode:sme">SME / 25 practices</button></div>`;
 return `${header('Product-security maturity','A structured, evidence-based improvement assessment with independently recorded current and target levels.')}${notice('Maturity levels describe process consistency and effectiveness. They are not CRA legal conformity levels or security certifications.')}${toggles}
 <div class="metrics four tight">${metric(m.assessed+'/'+m.total,'Controls rated')}${metric(m.average===null?'—':m.average+'/5','Average rated maturity')}${metric(m.below,'Below target')}${metric(m.coverage+'%','Assessment coverage')}</div>
 <div class="maturity-groups">${domains.map((domain,di)=>`<details id="maturity-group-${di}" class="panel maturity-group" ${di===0?'open':''}><summary class="maturity-domain"><strong>${esc(domain)}</strong><span class="subtle">${controls.filter(c=>c.domain===domain).length} controls</span></summary>
 ${controls.filter(c=>c.domain===domain).map(c=>{const a=x.maturity?.[c.id]||{};return `<details id="maturity-control-${c.id}" class="maturity-control"><summary><b>${c.id}</b> ${esc(c.title)} <span class="subtle">${a.current?'Level '+a.current:'Unrated'}</span></summary><div class="maturity-assessment">
 <p class="subtle">${esc(c.question||'Evaluate how the activity is consistently performed and evidenced for the product.')}</p>
 <div class="inline-form"><label class="mini-select">Current level<select data-maturity="${c.id}" data-maturity-field="current">${selected([['0','Unrated'],[1,'1 · Initial'],[2,'2 · Repeatable'],[3,'3 · Defined'],[4,'4 · Measured'],[5,'5 · Improving']],a.current||0)}</select></label><label class="mini-select">Target level<select data-maturity="${c.id}" data-maturity-field="target">${selected([1,2,3,4,5].map(n=>[n,n]),a.target||c.target)}</select></label></div>
 <div class="rubric"><strong>Assessment anchors</strong><ol>${(c.levels||['Initial / ad hoc','Partly repeatable','Documented and assigned','Applied and verified','Measured and improved']).map(z=>`<li>${esc(z)}</li>`).join('')}</ol></div>
 <label class="field"><span>Assessment rationale and evidence reference</span><textarea data-maturity="${c.id}" data-maturity-field="notes" rows="2">${esc(a.notes||'')}</textarea></label></div></details>`;}).join('')}</details>`).join('')}</div>`;
}
function traceabilityPage(){const x=p();if(!x)return header('Traceability')+requireProduct('Traceability');const rows=relevantRequirements(x);return `${header('Assurance traceability','Review recorded relationships between regulatory prompts, product risks, evidence and remediation.')}${notice('A relationship is only as strong as its documented justification. Presence of a link is not proof of compliance.')}<div class="panel table-panel"><div class="section-title"><h3>Requirement-to-evidence matrix</h3><span class="subtle">${rows.length} mapped prompts</span></div><div class="table-wrap"><table><thead><tr><th>Requirement</th><th>Assessment</th><th>Risk links</th><th>Evidence</th><th>Accepted</th><th>Open actions</th></tr></thead><tbody>${rows.map(r=>{const a=x.requirements[r.id]||{};const es=x.evidence.filter(e=>(e.requirementIds||[]).includes(r.id));return `<tr><td><b>${r.id}</b><small>${esc(r.title)}</small></td><td>${tag(STATUS_LABEL[a.status]||'Not assessed',a.status==='implemented'?'success':'neutral')}</td><td>${x.risks.filter(z=>(z.requirementIds||[]).includes(r.id)).length}</td><td>${es.length}</td><td>${es.filter(e=>e.review==='accepted').length}</td><td>${x.actions.filter(z=>(z.requirementIds||[]).includes(r.id)&&z.status!=='closed').length}</td></tr>`;}).join('')}</tbody></table></div></div>`;}
function evidencePage(){const x=p();if(!x)return header('Evidence register')+requireProduct('Evidence register');return `${header('Evidence register','Maintain traceable references and explicit reviewer decisions. Actual evidence files are never uploaded to this app.')}${notice('Evidence references are not documents: review and acceptance are separate manual decisions. Never place sensitive assessment information in a public GitHub repository.')}<div class="two-col wide-left"><div><div class="section-title"><h3>Evidence records</h3><span class="subtle">${x.evidence.length} entries</span></div>${x.evidence.length?x.evidence.map(e=>`<article class="record"><div class="record-title"><strong>${esc(e.title)}</strong>${tag(e.review||'unreviewed',e.review==='accepted'?'success':e.review==='rejected'?'danger':'neutral')}</div><div class="record-meta">${esc(e.reference||'No reference')} · ${esc((e.requirementIds||[]).join(', ')||'Not linked')}</div><p>${esc(e.description||'')}</p><div class="record-controls"><select data-evidence-review="${e.id}" aria-label="Evidence review state">${selected(REVIEWS.map(v=>[v,v[0].toUpperCase()+v.slice(1)]),e.review)}</select><button data-action="delete-evidence:${e.id}" class="button danger ghost">Delete</button></div></article>`).join(''):empty('No evidence yet','Add identifiers, document references or links. Do not upload actual client documents to the public app.')}</div><form class="panel form-layout" data-form="evidence"><div class="section-title"><h3>Record evidence</h3>${tag('Local only','blue')}</div>${field('Evidence title',input('title','','text','Example: SEC-TST-042'))}${field('Document reference / URL',input('reference','','text','Internal ID, hash or document link'))}${field('Linked requirement IDs',input('requirementIds','','text','A1-01, VH-02'),'Separate IDs with commas; IDs must exist in this catalogue.')}${field('Evidence description',textarea('description','','What does this demonstrate?'))}<button type="submit" class="button primary">Add evidence reference</button></form></div>`;}
function risksPage(){const x=p();if(!x)return header('Threats & risks')+requireProduct('Threats & risks');return `${header('Threats & product risks','An engineering-focused risk register, including STRIDE prompts and explicit residual-risk disposition.')}${notice('The 5×5 matrix below is a planning convention, not a legal threshold or CRA conformity score.')}<div class="two-col wide-left"><div><div class="section-title"><h3>Recorded threats and risks</h3><span class="subtle">${x.risks.length} cases</span></div>${x.risks.length?x.risks.map(r=>{const z=riskRating(r.likelihood,r.impact),res=riskRating(r.residualLikelihood,r.residualImpact);return `<article class="record"><div class="record-title"><strong>${esc(r.title)}</strong>${tag('Residual '+res.level,res.score>=10?'danger':'neutral')}</div><div class="record-meta">${esc(r.stride||'Uncategorised')} · ${esc((r.requirementIds||[]).join(', ')||'No CRA link')}</div><p>${esc(r.scenario)}</p><div class="risk-pills"><span>Inherent ${z.score}/25</span><span>Residual ${res.score}/25</span><span>${esc(r.acceptance||'Awaiting decision')}</span></div><div class="record-controls"><button data-action="accept-risk:${r.id}" class="button outline small">${r.acceptance==='accepted'?'Accepted (change)':'Record acceptance'}</button><button data-action="delete-risk:${r.id}" class="button danger ghost">Delete</button></div></article>`;}).join(''):empty('No product risks recorded','Identify a component, threat scenario, impact and proposed treatment.')}</div><form data-form="risk" class="panel form-layout"><h3>Add threat scenario</h3>${field('Risk name',input('title','','text','Example: Unauthorised firmware update'))}${field('STRIDE classification',select('stride',[['','Not classified'],...STRIDE.map(z=>[z[1],z[1]])],''))}${field('Scenario and consequence',textarea('scenario','','What could fail, why, and with what consequence?'))}${field('Linked requirement IDs',input('requirementIds','','text','A1-05, VH-07'))}<div class="form-grid">${field('Inherent likelihood (1–5)',select('likelihood',[1,2,3,4,5].map(n=>[n,n]),3))}${field('Inherent impact (1–5)',select('impact',[1,2,3,4,5].map(n=>[n,n]),3))}${field('Residual likelihood (1–5)',select('residualLikelihood',[1,2,3,4,5].map(n=>[n,n]),2))}${field('Residual impact (1–5)',select('residualImpact',[1,2,3,4,5].map(n=>[n,n]),3))}</div>${field('Mitigation / treatment',textarea('treatment'))}${field('Risk owner',input('owner'))}<button class="button primary" type="submit">Add risk</button></form></div>`;}
function actionsPage(){const x=p();if(!x)return header('Action plan')+requireProduct('Action plan');return `${header('Remediation board','Give each gap a clear owner, deadline and verification status.',btn('Create actions for gaps','seed-actions','outline'))}${notice('Items only close when marked by a user. The app cannot verify implementation, approvals or system changes.')}<div class="kanban">${STEPS.map(status=>`<div class="kanban-column"><h3>${status.replace('-',' ').replace(/\b\w/g,x=>x.toUpperCase())}<small>${x.actions.filter(a=>a.status===status).length}</small></h3>${x.actions.filter(a=>a.status===status).map(a=>`<div class="task-card"><strong>${esc(a.title)}</strong><p>${esc(a.description||'')}</p><small>Owner: ${esc(a.owner||'Unassigned')} · Due: ${esc(a.due||'—')}</small><select aria-label="Change action status" data-action-status="${a.id}">${selected(STEPS.map(s=>[s,s]),a.status)}</select><button class="button link danger" data-action="delete-action:${a.id}">Remove</button></div>`).join('')}</div>`).join('')}</div><form class="panel action-create" data-form="action"><h3>New remediation action</h3><div class="form-grid">${field('Action title',input('title'))}${field('Owner',input('owner'))}${field('Due date',input('due','','date'))}${field('Linked requirement IDs',input('requirementIds','','text','A1-03, VH-02'))}</div>${field('Description / verification criteria',textarea('description'))}<button class="button primary" type="submit">Add action</button></form>`;}
function releasesPage(){const x=p();if(!x)return header('Release reviews')+requireProduct('Release reviews');const review=releaseReview(x),last=x.releases.at(-1);const changes=last?compareSnapshot(x,last):[];return `${header('Release assurance','Capture a baseline at each version and review changes instead of assuming earlier conclusions remain valid.')}${notice('The gate is a checklist of recorded facts, not an automatic approval, legal determination or conformity declaration.')}<div class="two-col"><div class="panel"><div class="section-title"><h3>Outstanding review conditions</h3>${tag(review.issues.length+' flags',review.issues.length?'danger':'success')}</div>${review.issues.length?`<ul class="issue-list">${review.issues.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:notice('No automated flags remain. Formal release and conformity sign-off must still be performed by an authorised person.','success')}</div><div class="panel form-layout"><h3>Capture assessment snapshot</h3><p class="subtle">Snapshots capture requirement outcomes and headline counts. They are not a full immutable audit trail.</p><form data-form="snapshot">${field('Snapshot label',input('label',`Release review ${x.version}`))}<button class="button primary" type="submit">Save snapshot</button></form></div></div><div class="section"><div class="section-title"><h2>Assessment history</h2><span class="subtle">${x.releases.length} snapshots</span></div>${x.releases.length?`<div class="panel table-wrap"><table><thead><tr><th>Review</th><th>Version</th><th>Date</th><th>Coverage</th><th>Open actions</th></tr></thead><tbody>${x.releases.map(s=>`<tr><td>${esc(s.label)}</td><td>${esc(s.version)}</td><td>${esc(isoDate(s.date))}</td><td>${s.metrics.coverage}%</td><td>${s.actionOpen}</td></tr>`).join('')}</tbody></table></div>`:empty('No snapshots','Save the current assessment to compare later product versions.')}${last?`<div class="panel section"><h3>Changes since latest snapshot: ${changes.length}</h3>${changes.length?`<ul class="issue-list">${changes.map(c=>`<li>${c.id} — ${esc(c.before)} → ${esc(c.after)}</li>`).join('')}</ul>`:'<p class="subtle">No requirement statuses have changed.</p>'}</div>`:''}</div>`;}
function sbomPage(){const x=p();if(!x)return header('SBOM explorer')+requireProduct('SBOM explorer');return `${header('Software component inventory','Import CycloneDX or SPDX JSON locally to inspect components. No external feed lookup or vulnerability scanning.')}${notice('SBOM content is parsed in the browser. An inventory is not automatically evidence of vulnerability management and known vulnerabilities are not inferred.') }<div class="panel upload-panel"><div class="upload-icon">↓</div><div><h3>Import a software bill of materials</h3><p>CycloneDX JSON or SPDX 2.x JSON · Maximum 5 MB · Up to 10,000 components</p></div><label class="button primary upload-button">Select SBOM file<input id="sbom-upload" type="file" accept=".json,application/json" hidden/></label></div>${x.components.length?`<div class="section panel table-panel"><div class="section-title"><h3>Components (${x.components.length})</h3>${btn('Clear inventory','clear-sbom','outline small')}</div><div class="table-wrap"><table><thead><tr><th>Component</th><th>Version</th><th>Supplier</th><th>Licence</th></tr></thead><tbody>${x.components.slice(0,350).map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.purl||c.id)}</small></td><td>${esc(c.version)}</td><td>${esc(c.supplier||'—')}</td><td>${esc(c.licence||'—')}</td></tr>`).join('')}</tbody></table>${x.components.length>350?`<div class="notice">Showing the first 350 of ${x.components.length} components; the full inventory is retained in your browser workspace.</div>`:''}</div></div>`:empty('No software inventory imported','Import an existing machine-readable SBOM to inspect the component list.')}`;}
function vulnerabilitiesPage(){const x=p();if(!x)return header('Vulnerability register')+requireProduct('Vulnerability register');const vs=x.vulnerabilities||[];return `${header('Vulnerability management','Track product/component vulnerabilities, exploitation evidence, remediation and disclosure without external lookups.')}${notice('Severity and exploitation indicators must be supported by analyst evidence. This register does not scan products or determine mandatory Article 14 reporting.')}<div class="metrics four tight">${metric(vs.length,'Recorded vulnerabilities')}${metric(vs.filter(v=>v.status!=='resolved'&&v.status!=='risk-accepted').length,'Active')}${metric(vs.filter(v=>['critical','high'].includes(v.severity)&&!['resolved','risk-accepted'].includes(v.status)).length,'High / critical open')}${metric(vs.filter(v=>v.exploited==='yes').length,'Exploitation reported')}</div><div class="two-col wide-left"><div>${vs.length?vs.map(v=>`<article class="record"><div class="record-title"><strong>${esc(v.reference||v.title||'Vulnerability')}</strong>${tag(v.severity||'unrated',['critical','high'].includes(v.severity)?'danger':'neutral')}</div><div class="record-meta">${esc(v.component||'Product-wide')} · ${esc(v.status)} · ${esc(v.exploited==='yes'?'Exploitation reported':v.exploited==='unknown'?'Exploitation undetermined':'No exploitation evidence recorded')}</div><p>${esc(v.description||'')}</p><div class="record-controls"><select aria-label="Vulnerability workflow" data-vulnerability-status="${v.id}">${selected([['open','Open'],['investigating','Investigating'],['fix-in-progress','Remediation'],['resolved','Resolved / verified'],['risk-accepted','Risk accepted']],v.status)}</select><button class="button danger ghost" data-action="delete-vulnerability:${v.id}">Delete</button></div></article>`).join(''):empty('No vulnerability records','Add known issues affecting the product and document remediation or disposition.')}</div><form data-form="vulnerability" class="panel form-layout"><h3>Register a vulnerability</h3>${field('Reference / advisory identifier',input('reference','','text','CVE or internal ticket'))}${field('Affected component / product',input('component'))}${field('Issue summary',input('title'))}${field('Technical impact and discovery context',textarea('description'))}<div class="form-grid">${field('Severity',select('severity',[['unknown','Undetermined'],['low','Low'],['medium','Medium'],['high','High'],['critical','Critical']],'unknown'))}${field('Exploitation evidence',select('exploited',[['unknown','Undetermined'],['no','Not evidenced'],['yes','Reliable evidence recorded']],'unknown'))}</div>${field('Investigation / remediation owner',input('owner'))}${field('Corrective / mitigation measure',textarea('remedy'))}${field('Linked requirement IDs',input('requirementIds','','text','VH-02, A1-02'))}<button class="button primary" type="submit">Add vulnerability</button></form></div>`;}
function reportingPage(){const x=p();if(!x)return header('Incident reporting')+requireProduct('Incident reporting');const c=x.incident||{},dl=reportingDeadlines(c);return `${header('Article 14 reporting planner','Record incident facts and calculate the staged deadlines for human review.')}${notice('Reporting applies to actively exploited vulnerabilities and qualifying severe incidents. This tool does not verify a reporting trigger, file notifications or connect to the ENISA Single Reporting Platform.','warn')}<div class="two-col"><form class="panel form-layout" data-form="incident"><h3>Reporting case</h3>${field('Case type',select('kind',[['vulnerability','Actively exploited vulnerability'],['incident','Severe security incident']],c.kind||'vulnerability'))}${field('Case identifier',input('reference',c.reference||''))}${field('Reportability decision',select('trigger',[['unknown','Undetermined / investigate'],['yes','Trigger established'],['no','Not reportable on documented facts']],c.trigger||'unknown'))}${field('Awareness time (local timezone)',input('awareness',c.awareness||'','datetime-local'))}${field('Mitigation/corrective measure available',input('remedy',c.remedy||'','datetime-local'))}${field('72-hour notification submitted',input('notification',c.notification||'','datetime-local'))}${field('Incident facts and decision rationale',textarea('facts',c.facts||''))}<button class="button primary" type="submit">Save reporting case</button></form><div class="right-column"><div class="panel"><h3>Calculated milestone dates</h3>${dl?`<div class="deadline"><span>Early warning · 24 h</span><strong>${esc(dl.early.toLocaleString())}</strong></div><div class="deadline"><span>Follow-up notification · 72 h</span><strong>${esc(dl.notification.toLocaleString())}</strong></div><div class="deadline"><span>Final report</span><strong>${dl.final?esc(dl.final.toLocaleString()):'Requires further trigger date'}</strong></div>`:empty('Enter awareness time','The early warning and notification dates will appear here.')}</div><div class="panel"><h3>Regulatory reporting</h3><p>Use the official European reporting infrastructure and the relevant incident response process. This planning record is not a notification.</p><p class="legal-reference">Articles 14–16 · Regulation (EU) 2024/2847</p></div></div></div>`;}
function documentsPage(){const x=p();if(!x)return header('Technical documentation')+requireProduct('Technical documentation');const rev=releaseReview(x);return `${header('Technical documentation builder','Track Annex VII-aligned document categories and assemble a transparent review pack.')}${notice('Documentation coverage is illustrative. The exported report contains only recorded references and findings; it does not automatically create a compliant technical file.')}<div class="two-col wide-left"><form data-form="documents" class="panel form-layout"><h3>Documentation references</h3>${DOCS.map(d=>field(d.label,input(d.id,x.documents[d.id]?.reference||'','text','Document ID, version, location or link'))).join('')}<button type="submit" class="button primary">Save documentation register</button></form><div class="right-column"><div class="panel"><span class="eyebrow">REFERENCE COVERAGE</span><div class="huge">${DOCS.length-rev.missingDocs.length}<small> / ${DOCS.length}</small></div><p class="subtle">Categories with at least one recorded reference.</p><div class="thin-rule"></div><h4>Missing references</h4>${rev.missingDocs.length?`<ul class="issue-list">${rev.missingDocs.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`:'<p>All categories have recorded references, not necessarily validated evidence.</p>'}</div>${btn('Open printable review pack','print-report','primary')}</div></div>`;}
function settingsPage(){return `${header('Data & settings','Control local assessment data and understand the security boundaries of this static application.')}${notice('Browser localStorage is not an encrypted evidence repository. Avoid saving sensitive technical secrets or client information; back up data securely outside the public repository.','warn')}<div class="two-col"><div class="panel form-layout"><h3>Workspace data</h3><p>${work.products.length} products stored locally. Export before changing browsers, devices, origins or clearing site data.</p>${btn('Export full JSON backup','export-workspace','primary')}${btn('Export review tables (CSV)','csv-export','outline')}${btn('Download encrypted backup','encrypted-backup','outline')}<label class="button outline upload-button">Import JSON backup<input type="file" id="backup-import" accept=".json,application/json" hidden/></label>${btn('Load fictional demonstration','demo-product','outline')}${btn('Clear this browser workspace','clear-workspace','danger')}</div><div class="panel"><h3>About this edition</h3><p>A self-contained, offline-capable workspace with no accounts, remote backend, tracking scripts or external runtime dependencies.</p><p>Regulatory checklist: <strong>${REQUIREMENTS.length} authored assessment prompts</strong>. Each check is an editorial assessment aid and must be reviewed for legal applicability.</p><p>Previous-format JSON backups can be imported into an isolated archive for manual review. Custom question and maturity IDs are not silently remapped.</p><div class="thin-rule"></div><h4>Primary sources</h4>${REGULATORY_BASELINE.map(l=>`<p><strong>${esc(l.label)}</strong> — ${esc(l.ref)}</p>`).join('')}</div></div>`;}
function printDocument(){const x=p();if(!x)return;const m=requirementMetrics(x),rv=releaseReview(x);const html=`<!doctype html><html><head><meta charset="utf-8"><title>CRA Readiness Studio · ${esc(x.name)}</title><style>body{font:12px/1.5 Arial,sans-serif;color:#17283b;margin:30px auto;max-width:850px}h1{font-size:26px}h2{font-size:17px;margin-top:24px}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #ddd;padding:8px}small{color:#6c7781}.warning{padding:12px;border:1px solid #bcc;background:#eef5f7}.break{break-before:page}@media print{body{margin:12mm}h2{break-after:avoid}}</style></head><body><small>CRA READINESS STUDIO / INDEPENDENT ASSESSMENT RECORD</small><h1>${esc(x.name)}</h1><p>${esc(x.organisation)} · Version ${esc(x.version)} · Prepared ${esc(isoDate(new Date()))}</p><div class="warning"><b>Draft self-assessment:</b> This is not a declaration of conformity, certification or regulatory approval. Independent review and complete Annex VII documentation may be required.</div><h2>Scope and profile</h2><p>${esc(scope(x).status)} — ${esc(x.scopeRationale||'No rationale recorded')}</p><p>${esc(x.purpose)}</p><h2>Review metrics</h2><p>Coverage: ${m.coverage}% (${m.assessed}/${m.total}) · Accepted evidence links: ${m.linkedAccepted} · Open priority prompts: ${m.criticalOpen}</p><h2>Release review issues</h2><ul>${rv.issues.map(t=>`<li>${esc(t)}</li>`).join('')||'<li>No rule-based flags; human review is still required.</li>'}</ul><h2 class="break">Requirement assessment</h2><table><thead><tr><th>Ref</th><th>Prompt</th><th>Outcome</th><th>Recorded rationale</th></tr></thead><tbody>${relevantRequirements(x).map(r=>`<tr><td>${esc(r.ref)}</td><td>${esc(r.title)}</td><td>${esc(STATUS_LABEL[x.requirements[r.id]?.status]||'Unreviewed')}</td><td>${esc(x.requirements[r.id]?.notes||'')}</td></tr>`).join('')}</tbody></table><h2>Evidence references</h2><ul>${x.evidence.map(e=>`<li>${esc(e.title)}: ${esc(e.reference)} (${esc(e.review)})</li>`).join('')||'<li>None</li>'}</ul><h2>Cybersecurity risks</h2><ul>${x.risks.map(r=>`<li>${esc(r.title)} — ${esc(r.scenario)}</li>`).join('')||'<li>None</li>'}</ul><h2>Technical documentation references</h2><ul>${DOCS.map(d=>`<li>${esc(d.label)}: ${esc(x.documents[d.id]?.reference||'MISSING')}</li>`).join('')}</ul><h2>Product vulnerability records</h2><ul>${(x.vulnerabilities||[]).map(v=>`<li>${esc(v.reference||v.title)} / ${esc(v.severity)} / ${esc(v.status)}</li>`).join('')||'<li>None recorded</li>'}</ul><h2>Remediation actions</h2><ul>${x.actions.map(a=>`<li>${esc(a.title)} / ${esc(a.status)} / owner: ${esc(a.owner||'Unassigned')}</li>`).join('')||'<li>None recorded</li>'}</ul><h2>Software component inventory</h2><p>${x.components.length} imported components; SBOM data requires validation.</p><h2>Assessment history</h2><p>${x.releases.length} version snapshots saved for comparative review.</p><small>Legal reference: Regulation (EU) 2024/2847. Generated locally and never submitted to any authority.</small></body></html>`;const w=window.open('','_blank');if(!w){notify('Allow pop-ups to open the printable report.');return;}w.document.write(html);w.document.close();w.focus();}
function content(){switch(page){case'overview':return overview();case'product':return productPage();case'requirements':return requirementsPage();case'maturity':return maturityPage();case'traceability':return traceabilityPage();case'evidence':return evidencePage();case'risks':return risksPage();case'actions':return actionsPage();case'releases':return releasesPage();case'sbom':return sbomPage();case'vulnerabilities':return vulnerabilitiesPage();case'reporting':return reportingPage();case'documents':return documentsPage();case'settings':return settingsPage();default:return overview();}}
function render(){app.innerHTML=frame();}
const values=(form)=>Object.fromEntries([...new FormData(form).entries()]);
const parseIds=s=>String(s||'').split(/[,;\s]+/).map(s=>s.trim().toUpperCase()).filter(z=>REQUIREMENTS.some(r=>r.id===z)).filter((v,i,a)=>a.indexOf(v)===i);
function addDemo(){const x=newProduct('Industrial Edge Gateway · demo');Object.assign(x,{version:'2.2',organisation:'Illustrative manufacturer',owner:'Product security team',assessor:'Example assessor',eu:'yes',digital:'yes',commercial:'yes',exemption:'no',purpose:'Illustrative OT gateway linking field networks to a managed network; fictional example only.',scopeRationale:'Demonstration only — not a legal determination.'});REQUIREMENTS.forEach((r,i)=>{if(i%4!==3)x.requirements[r.id]={status:i%4===0?'implemented':i%4===1?'partial':'gap',notes:'Fictional assessment for UI demonstration.'};});x.evidence.push({id:uid(),title:'Architecture review record',reference:'DEMO-ARCH-01',description:'Illustrative evidence reference, not a real review.',requirementIds:['A1-01','A1-11'],review:'accepted'});x.risks.push({id:uid(),title:'Weak management interface authentication',stride:'Spoofing',scenario:'A remote user might impersonate an authorised administrator.',requirementIds:['A1-05'],likelihood:3,impact:4,residualLikelihood:2,residualImpact:3,treatment:'Enforce MFA and restrict administrative interfaces.',owner:'Engineering',acceptance:'open'});x.actions.push({id:uid(),title:'Verify firmware update process',owner:'Platform team',due:'',description:'Demonstrate authenticated signing and rollback behaviour.',status:'in-progress',requirementIds:['A1-04','VH-07']});work.products.push(x);work.productId=x.id;save();notify('Fictional demonstration added.');}
app.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;const x=p();
 if(a==='clear-toast'){toastText='';render();return;}
 if(a.startsWith('maturity-mode:')){maturityMode=a.split(':')[1]==='sme'?'sme':'professional';render();return;}
 if(a==='mobile-nav'){document.querySelector('#sidebar')?.classList.toggle('sidebar-open');return;}
 if(a==='reference'){navigate('requirements');return;}
 if(a==='new-product'){const n=newProduct(`New product ${work.products.length+1}`);work.products.push(n);work.productId=n.id;save();navigate('product');return;}
 if(a==='export-workspace'){downloadText('cra-readiness-studio-backup.json',exportWorkspace(work),'application/json');toastText='Backup downloaded. Store it securely.';render();return;}
 if(a==='csv-export'){const product=p();if(!product){notify('Create an assessment first.');return;}const escapeCSV=v=>{let t=String(v??'');if(/^[=+@\-\t\r]/.test(t))t="'"+t;return '"'+t.replaceAll('"','""')+'"';};const format=(rows)=>'\uFEFF'+rows.map(row=>row.map(escapeCSV).join(',')).join('\r\n');const list=[['ID','Domain','Legal provision','Question','Status','Rationale','Reviewer'],...relevantRequirements(product).map(q=>[q.id,q.domain,q.ref,q.title,product.requirements[q.id]?.status||'not-assessed',product.requirements[q.id]?.notes||'',product.requirements[q.id]?.reviewer||''])];downloadText('cra-readiness-assessment.csv',format(list),'text/csv;charset=utf-8');notify('Assessment CSV downloaded.');return;}
 if(a==='encrypted-backup'){const pass=prompt('Create a strong password for the encrypted backup. It cannot be recovered if lost.');if(!pass)return;if(pass.length<12){notify('Use at least 12 characters for an encrypted backup password.');return;}encryptWorkspace(exportWorkspace(work),pass).then(blob=>{downloadText('cra-readiness-studio-encrypted.json',JSON.stringify(blob,null,2),'application/json');notify('Encrypted backup downloaded; store the password securely.');}).catch(()=>notify('Encryption failed. Use a recent browser with Web Crypto support.'));return;}
 if(a==='demo-product'){addDemo();navigate('overview');return;}
 if(a==='clear-workspace'){if(confirm('Delete ALL products saved by this application in this browser? Export a backup before proceeding.')){work={schema:2,productId:null,products:[]};save();navigate('overview');}return;}
 if(a==='print-report'){printDocument();return;}
 if(a==='seed-actions'&&x){const gaps=relevantRequirements(x).filter(q=>['gap','partial'].includes(x.requirements[q.id]?.status));let added=0;for(const q of gaps){if(x.actions.some(z=>z.sourceRequirementId===q.id))continue;x.actions.push({id:uid(),title:'Resolve: '+q.title,description:'Assess gap, define treatment and retain verification evidence. '+q.ref,owner:'',due:'',status:'open',sourceRequirementId:q.id,requirementIds:[q.id]});added++;}save();notify(added+' linked remediation actions added; duplicates skipped.');return;}
 if(a==='clear-sbom'&&x){if(confirm('Clear the imported SBOM inventory for this product?')){x.components=[];save();}return;}
 if(a.startsWith('evidence-for:')){navigate('evidence');const r=a.split(':')[1];const inp=app.querySelector('[name=requirementIds]');if(inp)inp.value=r;return;}
 if(!x)return;
 const [command,id]=a.split(':');
 const kinds={'delete-evidence':'evidence','delete-risk':'risks','delete-action':'actions','delete-vulnerability':'vulnerabilities'};if(kinds[command]){if(confirm('Delete this record?')){x[kinds[command]]=x[kinds[command]].filter(t=>t.id!==id);save();}return;}
 if(command==='accept-risk'){const r=x.risks.find(z=>z.id===id);if(r){r.acceptance=r.acceptance==='accepted'?'open':'accepted';save();}return;}
});
app.addEventListener('change',async e=>{const t=e.target;const x=p();if(t.id==='choose-product'){work.productId=t.value;save();return;}if(t.id==='requirements-filter'){filter=t.value;render();return;}if(t.dataset.maturity&&x){const opened=[...document.querySelectorAll('.maturity-group[open],.maturity-control[open]')].map(z=>z.id);x.maturity??={};x.maturity[t.dataset.maturity]??={};x.maturity[t.dataset.maturity][t.dataset.maturityField]=String(t.value);save();for(const id of opened)document.getElementById(id)?.setAttribute('open','');return;}if(t.dataset.requirement&&x){x.requirements[t.dataset.requirement]??={};x.requirements[t.dataset.requirement][t.dataset.reqField]=t.value;save();const det=document.querySelector('#r-'+t.dataset.requirement);det?.setAttribute('open','');return;}if(t.dataset.evidenceReview&&x){const z=x.evidence.find(z=>z.id===t.dataset.evidenceReview);if(z){z.review=t.value;save();}return;}if(t.dataset.vulnerabilityStatus&&x){const v=x.vulnerabilities?.find(z=>z.id===t.dataset.vulnerabilityStatus);if(v){v.status=t.value;save();}return;}if(t.dataset.actionStatus&&x){const z=x.actions.find(z=>z.id===t.dataset.actionStatus);if(z){z.status=t.value;save();}return;}
 if(t.id==='sbom-upload'&&x){const f=t.files[0];if(!f)return;if(f.size>5*1024*1024){notify('SBOM is larger than the 5 MB limit.');return;}try{const z=readSbom(JSON.parse(await f.text()));x.components=z.components;x.sbomInfo={format:z.format,importedAt:z.importedAt};save();notify(`${z.components.length} components imported. No online vulnerability lookup performed.`);}catch(err){notify(err.message||'Cannot parse this SBOM.');}return;}
 if(t.id==='backup-import'){const f=t.files[0];if(!f)return;if(f.size>10*1024*1024){notify('Backup exceeds 10 MB.');return;}try{let contents=JSON.parse(await f.text());if(isEncryptedBackup(contents)){const pass=prompt('Password for this encrypted backup:');if(!pass)return;contents=JSON.parse(await decryptWorkspace(contents,pass));}const imported=parseBackup(contents);if(confirm('Replace the current browser workspace with this imported backup? Export the current workspace first if needed.')){work=imported;save();navigate('overview');notify('Backup imported. Review any preserved legacy fields.');}}catch(err){notify(err.message||'Import failed.');}}
});
app.addEventListener('input',e=>{if(e.target.id!=='requirement-search')return;search=e.target.value;const cursor=e.target.selectionStart;render();const el=document.querySelector('#requirement-search');el?.focus();el?.setSelectionRange(cursor,cursor);});
app.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const k=form.dataset.form;const v=values(form);const x=p();if(!x)return;
 if(k==='profile'){for(const key of ['name','version','organisation','owner','assessor','role','eu','digital','commercial','exemption','category','placed','supportEnd','purpose','scopeRationale'])x[key]=String(v[key]||'').trim();}
 if(k==='evidence'){if(!String(v.title||'').trim())return notify('Evidence title is required.');x.evidence.push({id:uid(),title:v.title,reference:v.reference,description:v.description,requirementIds:parseIds(v.requirementIds),review:'referenced'});}
 if(k==='risk'){if(!String(v.title||'').trim())return notify('Risk title is required.');x.risks.push({id:uid(),...v,requirementIds:parseIds(v.requirementIds),acceptance:'open'});}
 if(k==='action'){if(!String(v.title||'').trim())return notify('Action title is required.');x.actions.push({id:uid(),...v,requirementIds:parseIds(v.requirementIds),status:'open'});}
 if(k==='vulnerability'){if(!String(v.reference||v.title||'').trim())return notify('Enter an identifier or title.');x.vulnerabilities??=[];x.vulnerabilities.push({id:uid(),...v,status:'open',requirementIds:parseIds(v.requirementIds)});}
 if(k==='snapshot'){x.releases.push(createSnapshot(x,String(v.label||`Review ${x.version}`).slice(0,160)));}
 if(k==='incident')x.incident={...v};
 if(k==='documents')for(const d of DOCS)x.documents[d.id]={reference:String(v[d.id]||'').trim()};
 save();toastText=`${k[0].toUpperCase()+k.slice(1)} saved in this browser.`;render();});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next!==page)navigate(next);});
page=ROUTES.some(r=>r[0]===location.hash.slice(1))?location.hash.slice(1):'overview';render();
